method Dedup(a: seq<int>) returns (r: seq<int>)
  requires Sorted(a)
  ensures StrictlySorted(r)
  ensures forall x :: x in a <==> x in r
{
  if |a| == 0 {
    return [];
  }
  r := [a[0]];
  assert a[..1] == [a[0]];
  var k := 1;
  while k < |a|
    invariant 1 <= k <= |a|
    invariant |r| >= 1
    invariant StrictlySorted(r)
    invariant r[|r| - 1] == a[k - 1]
    invariant forall x :: x in a[..k] <==> x in r
  {
    assert a[..k + 1] == a[..k] + [a[k]];
    if a[k] != r[|r| - 1] {
      assert a[k - 1] <= a[k];
      assert forall i :: 0 <= i < |r| ==> r[i] < a[k];
      r := r + [a[k]];
    } else {
      assert r[|r| - 1] in r;
    }
    k := k + 1;
  }
  assert a[..|a|] == a;
}

