method IsSorted(a: seq<int>) returns (b: bool)
  ensures b <==> Sorted(a)
{
  if |a| <= 1 {
    return true;
  }
  var k := 1;
  while k < |a|
    invariant 1 <= k <= |a|
    invariant forall i, j :: 0 <= i < j < k ==> a[i] <= a[j]
  {
    if a[k - 1] > a[k] {
      assert !(0 <= k - 1 < k < |a| ==> a[k - 1] <= a[k]);
      return false;
    }
    assert forall i :: 0 <= i < k ==> a[i] <= a[k - 1] <= a[k];
    k := k + 1;
  }
  return true;
}

