lemma AppendSorted(s: seq<int>, x: int)
  requires Sorted(s)
  requires forall k :: 0 <= k < |s| ==> s[k] <= x
  ensures Sorted(s + [x])
{
  var t := s + [x];
  forall i, j | 0 <= i < j < |t|
    ensures t[i] <= t[j]
  {
    if j < |s| {
      assert t[i] == s[i] && t[j] == s[j];
    } else {
      assert j == |s|;
      assert t[i] == s[i] && t[j] == x;
    }
  }
}

method MergeSorted(a: seq<int>, b: seq<int>) returns (out: seq<int>)
  requires Sorted(a) && Sorted(b)
  ensures Sorted(out)
  ensures multiset(out) == multiset(a) + multiset(b)
{
  var i := 0;
  var j := 0;
  out := [];
  assert a[0..] == a;
  assert b[0..] == b;

  while i < |a| || j < |b|
    invariant 0 <= i <= |a|
    invariant 0 <= j <= |b|
    invariant Sorted(out)
    invariant forall k :: 0 <= k < |out| && i < |a| ==> out[k] <= a[i]
    invariant forall k :: 0 <= k < |out| && j < |b| ==> out[k] <= b[j]
    invariant multiset(out) + multiset(a[i..]) + multiset(b[j..]) == multiset(a) + multiset(b)
    decreases |a| - i + |b| - j
  {
    if i < |a| && (j == |b| || a[i] <= b[j]) {
      assert a[i..] == [a[i]] + a[i + 1..];
      AppendSorted(out, a[i]);
      if i + 1 < |a| {
        assert a[i] <= a[i + 1];
      }
      out := out + [a[i]];
      i := i + 1;
    } else {
      assert b[j..] == [b[j]] + b[j + 1..];
      AppendSorted(out, b[j]);
      if j + 1 < |b| {
        assert b[j] <= b[j + 1];
      }
      out := out + [b[j]];
      j := j + 1;
    }
  }

  assert a[i..] == [];
  assert b[j..] == [];
}

