lemma SwapMultiset(s1: seq<int>, s2: seq<int>, k: int, j: int)
  requires 0 <= k <= j < |s1| == |s2|
  requires forall i :: 0 <= i < |s1| && i != k && i != j ==> s2[i] == s1[i]
  requires s2[k] == s1[j] && s2[j] == s1[k]
  ensures multiset(s1) == multiset(s2)
{
  if k == j {
    assert s1 == s2;
  } else {
    var a1 := s1[..k];
    var b1 := s1[k+1..j];
    var c1 := s1[j+1..];
    assert s1 == a1 + [s1[k]] + b1 + [s1[j]] + c1;
    assert multiset(a1 + [s1[k]] + b1 + [s1[j]] + c1) ==
           multiset(a1 + [s1[k]] + b1 + [s1[j]]) + multiset(c1);
    assert multiset(a1 + [s1[k]] + b1 + [s1[j]]) ==
           multiset(a1 + [s1[k]] + b1) + multiset([s1[j]]);
    assert multiset(a1 + [s1[k]] + b1) ==
           multiset(a1 + [s1[k]]) + multiset(b1);
    assert multiset(a1 + [s1[k]]) == multiset(a1) + multiset([s1[k]]);

    var a2 := s2[..k];
    var b2 := s2[k+1..j];
    var c2 := s2[j+1..];
    assert s2 == a2 + [s2[k]] + b2 + [s2[j]] + c2;
    assert multiset(a2 + [s2[k]] + b2 + [s2[j]] + c2) ==
           multiset(a2 + [s2[k]] + b2 + [s2[j]]) + multiset(c2);
    assert multiset(a2 + [s2[k]] + b2 + [s2[j]]) ==
           multiset(a2 + [s2[k]] + b2) + multiset([s2[j]]);
    assert multiset(a2 + [s2[k]] + b2) ==
           multiset(a2 + [s2[k]]) + multiset(b2);
    assert multiset(a2 + [s2[k]]) == multiset(a2) + multiset([s2[k]]);

    assert a1 == a2;
    assert b1 == b2;
    assert c1 == c2;
    assert [s1[k]] == [s2[j]];
    assert [s1[j]] == [s2[k]];
  }
}

